/**
 * Cleanup of leftover VDB test databases (**destructive operation, explicit confirmation required**).
 *
 * Background: the instance collection count has hit the cap of 1500/1500, so new databases cannot be created for real-machine verification.
 * This script only reclaims the one-off databases generated by automated e2e, to free up space for new verification databases.
 *
 * Safety design (a deletion operation; better to delete too few than to delete wrongly):
 *   1. **Single prefix allowlist**: only delete databases starting with `memory-tdai-test-`, hardcoded in
 *      ALLOWED_PREFIX, with no override via external parameters.
 *   2. **Denylist second veto**: even if the prefix matches, anything in PROTECTED is skipped.
 *   3. **Dry-run by default**: without `--confirm` it only prints what would be deleted and does not touch data.
 *   4. Delete one by one + a failure does not abort; summarize at the end for easy diagnosis.
 *
 * Usage:
 *   node --import tsx scripts/cleanup-vdb-test-dbs.ts            # dry-run
 *   node --import tsx scripts/cleanup-vdb-test-dbs.ts --confirm   # actually delete
 */
import { TcvdbClient } from "../src/core/store/tcvdb/client.js";

const VDB_URL = process.env.VDB_URL;
const VDB_API_KEY = process.env.VDB_API_KEY;

if (!VDB_URL || !VDB_API_KEY) {
  console.error("Environment variables VDB_URL / VDB_API_KEY are required");
  process.exit(2);
}

/**
 * The only database name prefix allowed to be deleted -- hardcoded, not modifiable via parameters/environment variables.
 * These databases are generated by automated e2e (names contain a random run id) and are for one-off use.
 */
const ALLOWED_PREFIX = "memory-tdai-test-";

/** Second-veto list: not deleted even if matched. */
const PROTECTED: Array<(db: string) => boolean> = [
  (d) => d.startsWith("memory-tencentdb-testing"),
  (d) => d.startsWith("memory_dev_"),
  // The database currently used by .env.devcloud, must never be deleted
  (d) => d === (process.env.VDB_DATABASE ?? ""),
];

const CONFIRMED = process.argv.includes("--confirm");
const silent = { debug: () => {}, info: () => {}, warn: () => {}, error: () => {} };

function isDeletable(db: string): boolean {
  if (!db.startsWith(ALLOWED_PREFIX)) return false;
  return !PROTECTED.some((p) => p(db));
}

async function main() {
  const client = new TcvdbClient({
    url: VDB_URL!,
    username: process.env.VDB_USERNAME ?? "root",
    apiKey: VDB_API_KEY!,
    database: process.env.VDB_DATABASE ?? "default",
    timeout: 30_000,
    logger: silent,
  });

  const dbResp = await client.request<{ databases?: string[] }>("/database/list", {});
  const dbs = dbResp.databases ?? [];
  const targets = dbs.filter(isDeletable);

  console.log(`Total databases: ${dbs.length}`);
  console.log(`Matching "${ALLOWED_PREFIX}*" and not protected: ${targets.length}`);

  if (targets.length === 0) {
    console.log("No databases to clean up, exiting.");
    return;
  }

  if (!CONFIRMED) {
    console.log("\n[DRY-RUN] The following databases will be deleted (pass --confirm to actually execute):");
    for (const db of targets.slice(0, 20)) console.log(`  ${db}`);
    if (targets.length > 20) console.log(`  ... and ${targets.length - 20} more`);
    console.log(`\nTotal ${targets.length} databases. No deletion was executed.`);
    return;
  }

  console.log(`\nStarting deletion of ${targets.length} databases...`);
  let ok = 0;
  const failed: Array<{ db: string; err: string }> = [];

  for (const [i, db] of targets.entries()) {
    // Validate once more before deleting, to prevent the list from being accidentally polluted
    if (!isDeletable(db)) {
      failed.push({ db, err: "failed safety re-check, skipped" });
      continue;
    }
    try {
      await client.dropDatabase(db);
      ok++;
      if ((i + 1) % 50 === 0) console.log(`  Progress ${i + 1}/${targets.length}`);
    } catch (err) {
      failed.push({ db, err: err instanceof Error ? err.message : String(err) });
    }
  }

  console.log(`\nDone: ${ok} succeeded, ${failed.length} failed`);
  if (failed.length) {
    console.log("Failure details (first 10):");
    for (const f of failed.slice(0, 10)) console.log(`  ${f.db}: ${f.err}`);
  }
}

main().catch((err) => {
  console.error("cleanup failed:", err instanceof Error ? err.message : String(err));
  process.exitCode = 1;
});
